add_filter( 'woocommerce_structured_data_product', 'perfectpixel_schema_brand_identifier', 20, 2 );

function perfectpixel_schema_brand_identifier( $markup, $product ) {
	if ( empty( $markup['brand'] ) ) {
		$brand = '';
		if ( taxonomy_exists( 'product_brand' ) ) {
			$terms = get_the_terms( $product->get_id(), 'product_brand' );
			$brand = ( $terms && ! is_wp_error( $terms ) ) ? $terms[0]->name : '';
		}
		$brand = $brand ? $brand : trim( '{{schema_default_brand}}' );
		if ( $brand ) {
			$markup['brand'] = array( '@type' => 'Brand', 'name' => $brand );
		}
	}
	$has_gtin = ! empty( $markup['gtin'] ) || ! empty( $markup['gtin8'] ) || ! empty( $markup['gtin12'] ) || ! empty( $markup['gtin13'] ) || ! empty( $markup['gtin14'] );
	if ( ! $has_gtin && empty( $markup['mpn'] ) && 'yes' === '{{schema_sku_as_mpn}}' && $product->get_sku() ) {
		$markup['mpn'] = $product->get_sku();
	}
	return $markup;
}
